def start_observe_period(apps, schema_editor):
    """Connections that already exist when source rules ship are not cut
    off at once (DESIGN.md §13.2): for 14 days their authenticated requests
    are let through and their source addresses are recorded for approval.
    Installations without such a connection start enforcing immediately."""
    from django.utils import timezone
    Connection = apps.get_model('connect', 'Connection')
    Identity = apps.get_model('connect', 'InstallationIdentity')
    Audit = apps.get_model('connect', 'ConnectAuditEvent')
    ids = [str(pk) for pk in Connection.objects.filter(state__in=('active', 'suspended')).values_list('pk', flat=True)]
    ident = Identity.objects.order_by('pk').first()
    if not ids or ident is None:
        return
    until = timezone.now() + timedelta(days=14)
    Identity.objects.filter(pk=ident.pk).update(source_observe_until=until, source_observe_connections=ids)
    from agit8or_connect import audit as chain
    last = Audit.objects.order_by('-seq').first()
    seq = (last.seq + 1) if last else 1
    prev = last.hash if last else chain.GENESIS
    record = {'seq': seq, 'ts_us': int(time.time() * 1_000_000), 'operation': 'source_policy.observe_started',
              'result': 'ok', 'connection_id': '', 'tenant': '', 'scopes': [], 'actor': 'system',
              'initiating_app': '', 'correlation_id': str(uuid.uuid4()),
              'detail': {'until': until.isoformat(), 'connections': len(ids)}}
    Audit.objects.create(seq=seq, ts_us=record['ts_us'], connection_id='', initiating_app='', tenant='',
                         actor='system', operation=record['operation'], scopes=[], result='ok',
                         correlation_id=record['correlation_id'], detail=record['detail'], prev_hash=prev,
                         hash=chain.entry_hash(prev, record))
